  console.log(`| ${pad("Time to diagnose", 35)}| ${pad("Minutes (manual)", 18)}| ${pad("Seconds (auto)", 18)}|`);

  console.log("\n  Structured logging transforms debugging from guesswork into a deterministic lookup.\n");
}

